<script setup lang="ts">
import { computed,onMounted } from 'vue';import { RouterLink,RouterView,useRoute,useRouter } from 'vue-router';import { MessageSquareText,Library,Leaf,Brain,LogOut,SlidersHorizontal,ShieldCheck,FlaskConical,Compass } from 'lucide-vue-next';import { useAppStore } from './store';import UploadDrawer from './components/UploadDrawer.vue'
import WorkspaceSwitcher from './components/WorkspaceSwitcher.vue'
import CommandPalette from './components/CommandPalette.vue'
const store=useAppStore(),route=useRoute(),router=useRouter(),authPage=computed(()=>route.path==='/login')
onMounted(async()=>{await store.bootstrap();if(!store.user&&route.path!=='/login')router.replace('/login');else if(store.user&&route.path==='/login')router.replace('/chat')})
async function logout(){await store.logout();router.replace('/login')}
</script>
<template><div v-if="!store.bootstrapped" class="auth-page">正在恢复登录状态…</div><RouterView v-else-if="authPage"/><div v-else-if="store.user" :class="['shell',{'workspace-mode':store.capabilities?.features.workspaces}]"><aside class="rail"><div class="brand"><Leaf :size="23"/><span>Learning Q&A</span></div><WorkspaceSwitcher v-if="store.capabilities?.features.workspaces"/><nav><RouterLink to="/chat"><MessageSquareText/><span>对话</span></RouterLink><RouterLink to="/documents"><Library/><span>资料</span></RouterLink><RouterLink to="/memories"><Brain/><span>记忆</span></RouterLink><RouterLink v-if="store.capabilities?.features.capability_center" to="/capabilities"><Compass/><span>能力</span></RouterLink><RouterLink v-if="store.user.role==='admin'" to="/admin"><ShieldCheck/><span>管理</span></RouterLink><RouterLink v-if="store.capabilities?.features.model_center" to="/models"><SlidersHorizontal/><span>模型</span></RouterLink><RouterLink v-if="store.user.role==='admin'&&store.capabilities?.features.evaluation" to="/evaluations"><FlaskConical/><span>评测</span></RouterLink></nav><div class="identity"><span>{{store.user.username}}</span><small>{{store.user.role==='admin'?'平台管理员':'普通用户'}}</small><button class="icon" aria-label="退出登录" @click="logout"><LogOut/></button></div></aside><main><div v-if="store.error" class="global-error" role="alert">{{store.error}}</div><div v-if="store.workspaceChanging" class="workspace-loading" role="status">正在读取空间资料…</div><RouterView v-else :key="store.organizationId||'personal'"/></main><CommandPalette v-if="store.capabilities?.features.capability_center"/><UploadDrawer/></div><main v-else class="auth-page">正在跳转到登录页…</main></template>
<style scoped>.workspace-mode .rail nav{margin-top:22px;min-height:0;overflow-y:auto;flex:1;align-content:start}.workspace-mode .identity{padding-top:16px;flex-shrink:0}.workspace-loading{display:grid;place-items:center;min-height:60vh;color:var(--muted)}@media(max-width:640px){.rail nav{display:flex;overflow-x:auto;overflow-y:hidden;margin:0;gap:2px;padding:0}.rail nav a{flex:0 0 44px;min-width:44px}.workspace-mode .rail{grid-template-columns:70px minmax(0,1fr) 34px;height:70px;align-items:center;gap:5px}.workspace-mode .rail nav{display:flex;flex:initial;overflow-x:auto;overflow-y:hidden;height:58px;margin:0;padding:0;gap:2px}.workspace-mode .rail .identity{padding:0;border:0;align-items:center;justify-content:center}.workspace-mode .identity>span,.workspace-mode .identity>small{display:none}.workspace-mode .rail :deep(.workspace-trigger){width:70px;height:58px;margin:0;padding:5px;gap:2px}}
</style>
